const scenarios={
 fast:{note:'乐观：材料 6–8 周完成、乡村优先审理较快、签证名额持续 Current。',ead:'2027 Q2',ap:'2027 Q3',gc:'2029–2030',perm:'2033–2035',events:[['2026-10 至 11','SOF、项目尽调、独立律师入境审查','blue'],['2026-12','I‑526E + I‑485/765/131 递交','blue'],['2027 Q2','EAD 工作许可','blue'],['2027 Q3','AP / Combo','blue'],['2029','I‑526E 与 I‑485 批准窗口','blue'],['2029–2030','项目预期偿还窗口','gold'],['2031–2032','I‑829 递交','blue'],['2033–2035','十年绿卡','blue']]},
 base:{note:'基准：充分尽调后递交，EAD/AP 分开获批，I‑526E 与 I‑485 受正常积压影响。',ead:'2027 Q2–Q4',ap:'2027 Q3–2028 Q3',gc:'2029–2032',perm:'2034–2038+',events:[['2026-10 至 12','SOF、项目尽调、独立律师入境审查','blue'],['2027 Q1','I‑526E + I‑485/765/131 递交','blue'],['2027 Q2–Q4','EAD 工作许可','blue'],['2027 Q3–2028 Q3','AP / Combo','blue'],['2027-09-30','区域中心法案到期/续期节点','red'],['2029–2032','有条件绿卡窗口','blue'],['2029–2031+','项目偿还窗口（与绿卡不同步）','gold'],['2031–2034','I‑829 递交','blue'],['2034–2038+','十年绿卡','blue']]},
 slow:{note:'压力：法案短暂停摆、签证倒退或 RFE，项目使用全部延长期。',ead:'2027–2028',ap:'2028–2029',gc:'2032–2035+',perm:'2037–2042+',events:[['2026 Q4–2027 Q1','材料与项目文件延迟','red'],['2027 Q1–Q2','并行递交','blue'],['2027–2029','EAD / AP 等待与续期','blue'],['2027–2028','法案停摆或补救立法','red'],['2032–2035+','有条件绿卡','blue'],['2031+','贷款延长、再融资或执行','gold'],['2034–2037','I‑829 递交','blue'],['2037–2042+','十年绿卡','blue']]}
};
function render(key){const s=scenarios[key];document.querySelectorAll('.scenario-tabs button').forEach(b=>b.classList.toggle('active',b.dataset.scenario===key));document.getElementById('scenarioNote').textContent=s.note;document.getElementById('eadDate').textContent=s.ead;document.getElementById('apDate').textContent=s.ap;document.getElementById('gcDate').textContent=s.gc;document.getElementById('permDate').textContent=s.perm;document.getElementById('timelineTrack').innerHTML=s.events.map(e=>`<div class="event ${e[2]}"><b>${e[0]}</b><span>${e[1]}</span></div>`).join('')}
document.querySelectorAll('.scenario-tabs button').forEach(b=>b.addEventListener('click',()=>render(b.dataset.scenario)));document.getElementById('printBtn').addEventListener('click',()=>window.print());render('base');
